CREATE OR REPLACE FUNCTION public.admin_add_source(p_name text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare saved text;
begin
 if not public.is_admin() then raise exception 'Admin эрх шаардлагатай.' using errcode='42501'; end if;
 insert into public.problem_sources as s(name) values(public.normalize_problem_source(p_name))
 on conflict(lower(name)) do update set name=s.name returning name into saved;
 return saved;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_archive_problem(p_number bigint, p_revision integer, p_archived boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.problem_catalog%rowtype; begin
 if not public.is_admin() then raise exception 'Admin эрх шаардлагатай.' using errcode='42501'; end if;
 if p_archived is null then raise exception 'Үйлдлээ сонгоно уу.'; end if;
 select * into r from public.problem_catalog where number=p_number for update;
 if r.problem_id is null then raise exception 'Бодлого олдсонгүй.'; end if;
 if r.revision is distinct from p_revision then raise exception 'Бодлого өөрчлөгдсөн байна. Дахин ачаална уу.' using errcode='40001'; end if;
 update public.problem_catalog set archived=p_archived,revision=revision+1,updated_at=now() where problem_id=r.problem_id;
 insert into public.problem_changes(problem_id,actor_id,action,previous_body,next_body) values(r.problem_id,auth.uid(),case when p_archived then 'archive' else 'restore' end,r.body,r.body);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_grant(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not public.is_admin() then raise exception 'Admin эрх шаардлагатай.' using errcode='42501'; end if;
 if p_user_id is null or not exists(select 1 from public.profiles where user_id=p_user_id) then raise exception 'Хэрэглэгч олдсонгүй.'; end if;
 insert into public.admin_accounts(user_id) values(p_user_id) on conflict do nothing;
 if found then insert into public.admin_grants(actor_id,target_id) values(auth.uid(),p_user_id); end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_import_learning_problems(p_problems jsonb, p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item jsonb;old public.problem_catalog%rowtype;saved jsonb;result jsonb:='[]'::jsonb;seen_urls text[]:='{}';seen_refs text[]:='{}';ref_key text;url_key text;
begin
 if not public.is_admin() then raise exception 'Admin эрх шаардлагатай.' using errcode='42501';end if;
 if jsonb_typeof(p_problems) is distinct from 'array' or jsonb_array_length(p_problems) not between 1 and 50 or pg_column_size(p_problems)>524288 then raise exception '1–50 бодлогын batch шаардлагатай.';end if;
 if p_dry_run is null then raise exception 'Dry run төлөв шаардлагатай.';end if;
 perform pg_catalog.pg_advisory_xact_lock(72483160);
 for item in select value from jsonb_array_elements(p_problems) loop
  item:=public.validate_learning_problem(item);url_key:=rtrim(item->>'url','/');ref_key:=lower(item->>'source')||'|'||lower(btrim(item->>'ref'));
  if url_key=any(seen_urls) or ref_key=any(seen_refs) then result:=result||jsonb_build_array(jsonb_build_object('status','duplicate_batch','ref',item->>'ref'));continue;end if;
  seen_urls:=array_append(seen_urls,url_key);seen_refs:=array_append(seen_refs,ref_key);
  select * into old from public.problem_catalog p where rtrim(p.body->>'url','/')=url_key or (lower(p.body->>'source')=lower(item->>'source') and lower(btrim(p.body->>'ref'))=lower(btrim(item->>'ref'))) limit 1;
  if found then result:=result||jsonb_build_array(jsonb_build_object('status','exists','id',old.problem_id,'ref',item->>'ref','archived',old.archived));
  elsif p_dry_run then result:=result||jsonb_build_array(jsonb_build_object('status','new','ref',item->>'ref','title',item->>'title'));
  else saved:=public.admin_save_problem(item);result:=result||jsonb_build_array(jsonb_build_object('status','created','id',saved->>'id','ref',item->>'ref'));end if;
 end loop;return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_import_problems(p_problems jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare task_body jsonb; result jsonb:='[]'::jsonb; saved jsonb; idx integer:=0;
begin
 if not public.is_admin() then raise exception 'Admin эрх шаардлагатай.' using errcode='42501'; end if;
 if p_problems is null or jsonb_typeof(p_problems)<>'array' then raise exception 'Бодлогын жагсаалт оруулна уу.'; end if;
 if jsonb_array_length(p_problems) not between 1 and 200 or pg_column_size(p_problems)>2097152 then raise exception 'Нэг удаад 1–200 бодлого, 2 MB хүртэл байна.'; end if;
 -- Entire batch is one transaction. Concurrent imports cannot bypass duplicate checks.
 perform pg_catalog.pg_advisory_xact_lock(72483160);
 for task_body in select value from jsonb_array_elements(p_problems) loop
  idx:=idx+1;
  begin
   if exists(select 1 from public.problem_catalog p where p.body->>'url'=task_body->>'url' or (lower(p.body->>'source')=lower(public.normalize_problem_source(task_body->>'source')) and lower(btrim(p.body->>'ref'))=lower(btrim(task_body->>'ref')))) then
    raise exception 'Энэ бодлого санд байна (хассан бодлого ч багтана).';
   end if;
   saved:=public.admin_save_problem(task_body);
   result:=result||jsonb_build_array(saved);
  exception when others then raise exception 'Бодлого %: %',idx,sqlerrm;
  end;
 end loop;
 return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_publish_tutorial_draft(p_id text, p_body jsonb, p_base_revision integer, p_draft_revision integer, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.tutorial_drafts%rowtype;t public.tutorial_catalog%rowtype;old_body jsonb;next_revision integer;remaining jsonb;
begin
 if not public.is_admin() or auth.uid() is distinct from p_actor then raise exception 'Admin/actor mismatch.' using errcode='42501';end if;
 perform pg_catalog.pg_advisory_xact_lock(72483161);
 select * into d from public.tutorial_drafts where tutorial_id=p_id and editor_id=auth.uid() for update;
 select * into t from public.tutorial_catalog where id=p_id for update;
 if d.tutorial_id is null or d.revision is distinct from p_draft_revision or d.base_revision is distinct from p_base_revision or coalesce(t.revision,0)<>p_base_revision then raise exception 'REVISION_CONFLICT: draft or publication changed.' using errcode='40001';end if;
 perform public.validate_tutorial_body(p_id,p_body);old_body:=coalesce(t.body,'{}'::jsonb);next_revision:=coalesce(t.revision,0)+1;
 insert into public.tutorial_catalog(id,body,revision,published,published_at,updated_by) values(p_id,p_body,next_revision,true,now(),auth.uid())
 on conflict(id) do update set body=excluded.body,revision=excluded.revision,published=true,published_at=now(),updated_at=now(),updated_by=auth.uid();
 insert into public.tutorial_changes(tutorial_id,actor_id,revision,previous_body,new_body) values(p_id,auth.uid(),next_revision,old_body,p_body);
 if d.body=p_body then delete from public.tutorial_drafts where tutorial_id=p_id and editor_id=auth.uid();
 else update public.tutorial_drafts set base_revision=next_revision,revision=revision+1,updated_at=now() where tutorial_id=p_id and editor_id=auth.uid() returning to_jsonb(tutorial_drafts)-'editor_id' into remaining;end if;
 return jsonb_build_object('body',p_body,'revision',next_revision,'published',true,'updated_at',now(),'draft',remaining);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_rebase_tutorial_draft(p_id text, p_body jsonb, p_current_revision integer, p_draft_revision integer, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.tutorial_drafts%rowtype;current_revision integer;
begin
 if not public.is_admin() or auth.uid() is distinct from p_actor then raise exception 'Admin/actor mismatch.' using errcode='42501';end if;
 if p_id is null or p_id !~ '^[a-z0-9-]{1,80}$' or jsonb_typeof(p_body) is distinct from 'object' or p_body->>'id' is distinct from p_id or pg_column_size(p_body)>1500000 then raise exception 'Invalid draft.' using errcode='22023';end if;
 perform pg_catalog.pg_advisory_xact_lock(72483161);
 select revision into current_revision from public.tutorial_catalog where id=p_id for update;
 select * into d from public.tutorial_drafts where tutorial_id=p_id and editor_id=auth.uid() for update;
 if coalesce(current_revision,0) is distinct from p_current_revision or coalesce(d.revision,0) is distinct from p_draft_revision then raise exception 'REVISION_CONFLICT: compare the latest versions again.' using errcode='40001';end if;
 insert into public.tutorial_drafts(tutorial_id,editor_id,body,base_revision,revision) values(p_id,auth.uid(),p_body,p_current_revision,1)
 on conflict(tutorial_id,editor_id) do update set body=excluded.body,base_revision=excluded.base_revision,revision=tutorial_drafts.revision+1,updated_at=now()
 returning * into d;
 return to_jsonb(d)-'editor_id';
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_problem(p_body jsonb, p_number bigint DEFAULT NULL::bigint, p_revision integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare current_row public.problem_catalog%rowtype;n bigint;task_id text;payload jsonb;pack text;rate integer;
begin
 if not public.is_admin() then raise exception 'Admin эрх шаардлагатай.' using errcode='42501'; end if;
 p_body:=public.validate_learning_problem(p_body);
 rate:=case when p_body->>'ratingKind'='unrated' then null else (p_body->>'rating')::integer end;
 perform pg_catalog.pg_advisory_xact_lock(72483160);
 p_body:=jsonb_set(p_body,'{source}',to_jsonb(public.admin_add_source(p_body->>'source')));
 pack:=case when lower(p_body->>'source')='cses' then 'cses' when lower(p_body->>'source')='egoi' then 'egoi' when rate<=1100 then 'foundation' when rate<=1500 then 'core' when rate<=1800 then 'challenge' when rate<=2100 then 'stretch' else 'advanced' end;
 if p_number is null then
  n:=pg_catalog.nextval('public.problem_number_seq');
  task_id:=case when lower(p_body->>'source')='cses' and p_body->>'ref' ~ '^[0-9]+$' then 'cses-'||(p_body->>'ref') when lower(p_body->>'source')='atcoder' and p_body->>'ref' ~* '^dp_[a-z]$' then 'atcoder-'||lower(p_body->>'ref') else 'task-'||n::text end;
 else
  select * into current_row from public.problem_catalog where number=p_number for update;
  if current_row.problem_id is null then raise exception 'Бодлого олдсонгүй.'; end if;
  if current_row.revision is distinct from p_revision then raise exception 'REVISION_CONFLICT: дахин ачаалж засна уу.' using errcode='40001'; end if;
  n:=current_row.number;task_id:=current_row.problem_id;
 end if;
 payload:=jsonb_build_object('id',task_id,'number',n,'pack',pack,'title',btrim(p_body->>'title'),'source',p_body->>'source','ref',btrim(p_body->>'ref'),'url',p_body->>'url','rating',rate,'ratingKind',p_body->>'ratingKind','priority',(p_body->>'priority')::boolean,'level',coalesce(p_body->>'level','Practice'),'tags',p_body->'tags','hints',coalesce(p_body->'hints','[]'::jsonb),'hintsEn',coalesce(p_body->'hintsEn','[]'::jsonb),'lesson',coalesce(p_body->>'lesson',''));
 if coalesce(p_body->>'editorialUrl','')<>'' then payload:=payload||jsonb_build_object('editorialUrl',p_body->>'editorialUrl'); end if;
 payload:=payload||jsonb_strip_nulls(jsonb_build_object('sourceId',p_body->>'sourceId','sourceCategory',p_body->>'sourceCategory','verifiedAt',p_body->>'verifiedAt','difficultyCategory',p_body->>'difficultyCategory','ratingBasis',p_body->>'ratingBasis','ratingConfidence',p_body->>'ratingConfidence','ratingEstimatedAt',p_body->>'ratingEstimatedAt'));
 if p_number is null then insert into public.problem_catalog(problem_id,number,body) values(task_id,n,payload);
 else update public.problem_catalog set body=payload,revision=revision+1,updated_at=now() where problem_id=task_id;end if;
 insert into public.problem_changes(problem_id,actor_id,action,previous_body,next_body) values(task_id,auth.uid(),case when p_number is null then 'create' else 'edit' end,current_row.body,payload);
 return payload||jsonb_build_object('revision',coalesce(current_row.revision,0)+1,'archived',coalesce(current_row.archived,false));
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_tutorial(p_id text, p_body jsonb, p_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old public.tutorial_catalog%rowtype; saved public.tutorial_catalog%rowtype;
begin
 if auth.uid() is null or not public.is_admin() then raise exception 'Admin эрх шаардлагатай.' using errcode='42501'; end if;
 perform public.validate_tutorial_body(p_id,p_body);
 select * into old from public.tutorial_catalog where id=p_id for update;
 if not found then raise exception 'Tutorial not found.' using errcode='22023'; end if;
 if p_revision is distinct from old.revision then raise exception 'REVISION_CONFLICT: reload this tutorial.' using errcode='40001'; end if;
 update public.tutorial_catalog set body=p_body,revision=old.revision+1,updated_at=now(),updated_by=auth.uid() where id=p_id returning * into saved;
 insert into public.tutorial_changes(tutorial_id,actor_id,revision,previous_body,new_body) values(p_id,auth.uid(),saved.revision,old.body,saved.body);
 return jsonb_build_object('body',saved.body,'revision',saved.revision);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_tutorial_draft(p_id text, p_body jsonb, p_base_revision integer, p_draft_revision integer, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.tutorial_drafts%rowtype;
begin
 if not public.is_admin() or auth.uid() is distinct from p_actor then raise exception 'Admin/actor mismatch.' using errcode='42501';end if;
 if p_id is null or p_id !~ '^[a-z0-9-]{1,80}$' or jsonb_typeof(p_body) is distinct from 'object' or p_body->>'id' is distinct from p_id or pg_column_size(p_body)>1500000 or p_base_revision is null or p_base_revision<0 or p_draft_revision is null or p_draft_revision<0 then raise exception 'Invalid draft.' using errcode='22023';end if;
 perform pg_catalog.pg_advisory_xact_lock(72483161);
 select * into d from public.tutorial_drafts where tutorial_id=p_id and editor_id=auth.uid() for update;
 if coalesce(d.revision,0)<>p_draft_revision then raise exception 'REVISION_CONFLICT: draft changed.' using errcode='40001';end if;
 if d.tutorial_id is not null and d.base_revision<>p_base_revision then raise exception 'REVISION_CONFLICT: draft base changed.' using errcode='40001';end if;
 insert into public.tutorial_drafts(tutorial_id,editor_id,body,base_revision,revision) values(p_id,auth.uid(),p_body,p_base_revision,1)
 on conflict(tutorial_id,editor_id) do update set body=excluded.body,revision=tutorial_drafts.revision+1,updated_at=now()
 returning * into d;return to_jsonb(d)-'editor_id';
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_tutorial_publication(p_id text, p_revision integer, p_published boolean, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.tutorial_catalog%rowtype;remaining jsonb;
begin
 if not public.is_admin() or auth.uid() is distinct from p_actor then raise exception 'Admin/actor mismatch.' using errcode='42501';end if;
 if p_published is null then raise exception 'Publication state required.' using errcode='22023';end if;
 perform pg_catalog.pg_advisory_xact_lock(72483161);select * into t from public.tutorial_catalog where id=p_id for update;
 if t.id is null or t.revision is distinct from p_revision then raise exception 'REVISION_CONFLICT: publication changed.' using errcode='40001';end if;
 if not p_published and exists(select 1 from public.tutorial_catalog other where other.published and other.id<>p_id and coalesce(other.body->'prerequisiteIds','[]'::jsonb) ? p_id) then raise exception 'A published tutorial still requires this prerequisite.' using errcode='22023';end if;
 update public.tutorial_catalog set published=p_published,revision=revision+1,updated_at=now(),updated_by=auth.uid(),published_at=case when p_published then now() else published_at end where id=p_id;
 insert into public.tutorial_changes(tutorial_id,actor_id,revision,previous_body,new_body) values(p_id,auth.uid(),t.revision+1,t.body,t.body);
 update public.tutorial_drafts set base_revision=t.revision+1,revision=revision+1,updated_at=now() where tutorial_id=p_id and editor_id=auth.uid() and base_revision=t.revision returning to_jsonb(tutorial_drafts)-'editor_id' into remaining;
 return jsonb_build_object('body',t.body,'revision',t.revision+1,'published',p_published,'updated_at',now(),'draft',remaining);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_store_learning_tutorial(p_body jsonb, p_revision integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare tid text:=p_body->>'id';current_row public.tutorial_catalog%rowtype;
begin
 if not public.is_admin() then raise exception 'Admin эрх шаардлагатай.' using errcode='42501';end if;
 perform public.validate_tutorial_body(tid,p_body);perform pg_catalog.pg_advisory_xact_lock(72483161);
 select * into current_row from public.tutorial_catalog where id=tid for update;
 if found then return public.admin_save_tutorial(tid,p_body,p_revision);end if;
 if p_revision<>0 then raise exception 'REVISION_CONFLICT: reload tutorial.' using errcode='40001';end if;
 insert into public.tutorial_catalog(id,body,revision,updated_by) values(tid,p_body,1,auth.uid());
 return jsonb_build_object('body',p_body,'revision',1);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_tutorial_document(p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not public.is_admin() then raise exception 'Admin required.' using errcode='42501';end if;
 return jsonb_build_object('current',(select jsonb_build_object('body',body,'revision',revision,'published',published,'updated_at',updated_at) from public.tutorial_catalog where id=p_id),
 'draft',(select to_jsonb(d)-'editor_id' from public.tutorial_drafts d where d.tutorial_id=p_id and d.editor_id=auth.uid()));
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_tutorial_history(p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not public.is_admin() then raise exception 'Admin required.' using errcode='42501';end if;
 return coalesce((select jsonb_agg(jsonb_build_object('revision',revision,'title',body->>'title','updated_at',stamp) order by revision desc) from (
  select distinct on(revision) revision,body,stamp from (
   select revision,body,updated_at stamp from public.tutorial_catalog where id=p_id
   union all select revision,new_body,created_at from public.tutorial_changes where tutorial_id=p_id
   union all select revision-1,previous_body,created_at from public.tutorial_changes where tutorial_id=p_id and revision>1
  ) versions where body->>'id'=p_id order by revision desc,stamp desc limit 50
 ) v),'[]'::jsonb);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_tutorial_history_body(p_id text, p_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 if not public.is_admin() then raise exception 'Admin required.' using errcode='42501';end if;
 select body into result from (
  select revision,body,updated_at stamp from public.tutorial_catalog where id=p_id
  union all select revision,new_body,created_at from public.tutorial_changes where tutorial_id=p_id
  union all select revision-1,previous_body,created_at from public.tutorial_changes where tutorial_id=p_id and revision>1
 ) v where revision=p_revision and body->>'id'=p_id order by stamp desc limit 1;
 if result is null then raise exception 'Revision not found.' using errcode='22023';end if;return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_tutorial_workspace()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not public.is_admin() then raise exception 'Admin required.' using errcode='42501';end if;
 return jsonb_build_object('catalog',coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',body->>'title','category',body->>'category','levelKey',body->>'levelKey','published',published,'revision',revision,'updated_at',updated_at) order by body->>'title') from public.tutorial_catalog),'[]'::jsonb),
 'drafts',coalesce((select jsonb_agg(jsonb_build_object('tutorial_id',tutorial_id,'title',body->>'title','category',body->>'category','levelKey',body->>'levelKey','revision',revision,'base_revision',base_revision,'updated_at',updated_at) order by updated_at desc) from public.tutorial_drafts where editor_id=auth.uid()),'[]'::jsonb));
end;
$function$

CREATE OR REPLACE FUNCTION public.can_cleanup_tutorial_media(p_path text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not public.is_admin() then return false;end if;
 perform pg_catalog.pg_advisory_xact_lock(72483161);
 return exists(select 1 from storage.objects where bucket_id='tutorial-media' and name=p_path and created_at<now()-interval '7 days')
 and not exists(select 1 from public.tutorial_media_references where object_path=p_path);
end;
$function$

CREATE OR REPLACE FUNCTION public.check_tutorial_media_exists()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p text;
begin
 perform pg_catalog.pg_advisory_xact_lock(72483161);
 if new.published then
  for p in select path from public.tutorial_image_paths(new.body) loop
   if auth.uid() is not null and not public.can_read_tutorial_media(p) then raise exception 'Image is not accessible to this editor.' using errcode='42501';end if;
   if not exists(select 1 from storage.objects where bucket_id='tutorial-media' and name=p) then raise exception 'Image is missing from Storage: %',p using errcode='22023';end if;
  end loop;
 end if;return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.follow_action(p_user_id uuid, p_follow boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me uuid:=auth.uid(); begin
 if me is null then raise exception 'Нэвтэрнэ үү.' using errcode='42501'; end if;
 if p_user_id is null or p_user_id=me or not exists(select 1 from public.profiles where user_id=p_user_id) then raise exception 'Өөр хэрэглэгч сонгоно уу.'; end if;
 if p_follow is null then raise exception 'Follow үйлдлээ сонгоно уу.'; end if;
 if p_follow then insert into public.following(follower_id,followed_id) values(me,p_user_id) on conflict do nothing;
 else delete from public.following where follower_id=me and followed_id=p_user_id; end if;
 return p_follow;
end;
$function$

CREATE OR REPLACE FUNCTION public.follow_friend_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if TG_OP='INSERT' or (old.status is distinct from new.status and new.status='accepted') then
  insert into public.following(follower_id,followed_id)
  values(new.requested_by,case when new.requested_by=new.user_low then new.user_high else new.user_low end)
  on conflict do nothing;
  if new.status='accepted' then
   insert into public.following(follower_id,followed_id)
   values(case when new.requested_by=new.user_low then new.user_high else new.user_low end,new.requested_by)
   on conflict do nothing;
  end if;
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.friend_action(p_user_id uuid, p_action text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me uuid:=auth.uid(); lo uuid; hi uuid; f public.friendships%rowtype;
begin
 if me is null then raise exception 'Нэвтэрнэ үү.' using errcode='42501'; end if;
 if me=p_user_id or p_user_id is null then raise exception 'Өөр хэрэглэгч сонгоно уу.'; end if;
 if not exists(select 1 from public.profiles where user_id=p_user_id) then raise exception 'Хэрэглэгч олдсонгүй.'; end if;
 lo:=least(me,p_user_id);hi:=greatest(me,p_user_id);
 -- Serialize actions on a pair, including simultaneous opposite requests.
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(lo::text||hi::text,0));
 select * into f from public.friendships where user_low=lo and user_high=hi for update;
 if p_action='request' then
  if f.user_low is not null then raise exception 'Хүсэлт эсвэл найзын холбоо аль хэдийн байна.'; end if;
  insert into public.friendships(user_low,user_high,requested_by) values(lo,hi,me);return 'outgoing';
 elsif p_action='accept' then
  if f.status is distinct from 'pending' or f.requested_by=me then raise exception 'Зөвшөөрөх хүсэлт олдсонгүй.'; end if;
  update public.friendships set status='accepted' where user_low=lo and user_high=hi;return 'friend';
 elsif p_action in ('decline','cancel','remove') then
  if f.user_low is null then raise exception 'Холбоо олдсонгүй.'; end if;
  if p_action='decline' and (f.status<>'pending' or f.requested_by=me) then raise exception 'Татгалзах хүсэлт олдсонгүй.'; end if;
  if p_action='cancel' and (f.status<>'pending' or f.requested_by<>me) then raise exception 'Цуцлах хүсэлт олдсонгүй.'; end if;
  if p_action='remove' and f.status<>'accepted' then raise exception 'Найзын холбоо олдсонгүй.'; end if;
  delete from public.friendships where user_low=lo and user_high=hi;return 'none';
 end if;
 raise exception 'Танихгүй үйлдэл.';
end;
$function$

CREATE OR REPLACE FUNCTION public.normalize_problem_source(p_name text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare name text;
begin
 name:=regexp_replace(btrim(p_name),'[[:space:]]+',' ','g');
 if name is null or name='' or length(name)>80 or p_name ~ '[[:cntrl:]]' then raise exception 'Source нэр 1–80 тэмдэгт байна.'; end if;
 return name;
end;
$function$

CREATE OR REPLACE FUNCTION public.refresh_tutorial_media_references()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s text;sid text;payload jsonb;
begin
 perform pg_catalog.pg_advisory_xact_lock(72483161);
 if TG_TABLE_NAME='tutorial_catalog' then s:='published';sid:=coalesce(new.id,old.id);
 elsif TG_TABLE_NAME='tutorial_drafts' then s:='draft';sid:=coalesce(new.editor_id,old.editor_id)::text||':'||coalesce(new.tutorial_id,old.tutorial_id);
 else s:='history';sid:=new.change_id::text;end if;
 delete from public.tutorial_media_references where scope=s and scope_id=sid;
 if TG_OP='DELETE' then return old;end if;
 if TG_TABLE_NAME='tutorial_catalog' then
  if not new.published then return new;end if;
 end if;
 if TG_TABLE_NAME='tutorial_changes' then payload:=jsonb_build_array(new.previous_body,new.new_body);else payload:=new.body;end if;
 insert into public.tutorial_media_references(scope,scope_id,object_path) select s,sid,path from public.tutorial_image_paths(payload) on conflict do nothing;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.study_add_member(p_group_id uuid, p_username text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target uuid;
begin
 perform 1 from public.study_groups where id=p_group_id for update;
 if not found or auth.uid() is null or not (study_private.is_member(p_group_id) or public.is_admin()) then
   raise exception 'Гишүүн нэмэхийн тулд энэ группын гишүүн байна.' using errcode='42501';
 end if;
 select user_id into target from public.profiles where username=lower(btrim(p_username));
 if target is null then raise exception 'Username олдсонгүй. Тухайн сурагч эхлээд бүртгүүлж, username-ээ тохируулна.' using errcode='22023'; end if;
 insert into public.study_group_members(group_id,user_id) values(p_group_id,target) on conflict do nothing;
 return target;
end;
$function$

CREATE OR REPLACE FUNCTION public.study_create_group(p_name text, p_description text DEFAULT ''::text, p_visibility text DEFAULT 'private'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare gid uuid;
begin
 if auth.uid() is null then raise exception 'Эхлээд нэвтэрнэ үү.' using errcode='42501'; end if;
 insert into public.study_groups(name,description,visibility,created_by)
 values(btrim(p_name),coalesce(p_description,''),p_visibility,auth.uid()) returning id into gid;
 insert into public.study_group_members(group_id,user_id,role) values(gid,auth.uid(),'admin');
 return gid;
end;
$function$

CREATE OR REPLACE FUNCTION public.study_member_role(p_group_id uuid, p_user_id uuid, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_role text;
begin
 perform 1 from public.study_groups where id=p_group_id for update;
 if not found or not study_private.can_manage(p_group_id) then raise exception 'Группын админ эрх шаардлагатай.' using errcode='42501'; end if;
 if p_role is null or p_role not in ('admin','member','remove') then raise exception 'Буруу эрх.' using errcode='22023'; end if;
 select role into old_role from public.study_group_members where group_id=p_group_id and user_id=p_user_id;
 if old_role is null then raise exception 'Гишүүн олдсонгүй.' using errcode='22023'; end if;
 if old_role='admin' and p_role<>'admin' and (select count(*) from public.study_group_members where group_id=p_group_id and role='admin')<=1 then
   raise exception 'Групп дор хаяж нэг админтай байна. Эхлээд өөр гишүүнд админ эрх өгнө үү.' using errcode='22023';
 end if;
 if p_role='remove' then
   delete from public.study_group_members where group_id=p_group_id and user_id=p_user_id;
 else
   update public.study_group_members set role=p_role where group_id=p_group_id and user_id=p_user_id;
 end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.study_save_report(p_group_id uuid, p_user_id uuid, p_date date, p_fields jsonb, p_expected_revision integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_row public.study_reports%rowtype; new_row public.study_reports%rowtype;
 count_value integer; fld text; field_limit integer;
begin
 -- Lock group before checking membership; removal/role changes use the same lock.
 perform 1 from public.study_groups where id=p_group_id for update;
 if not found or auth.uid() is null or not (study_private.can_manage(p_group_id) or
    (p_user_id=auth.uid() and study_private.is_member(p_group_id))) then
   raise exception 'Зөвхөн өөрийн тэмдэглэлээ засна. Бусдын тэмдэглэлд админ эрх шаардлагатай.' using errcode='42501';
 end if;
 if p_date is null or not isfinite(p_date) then raise exception 'Огноо сонгоно уу.' using errcode='22023'; end if;
 select * into old_row from public.study_reports where group_id=p_group_id and user_id=p_user_id and report_date=p_date for update;
 if not exists(select 1 from public.study_group_members where group_id=p_group_id and user_id=p_user_id) and old_row.user_id is null then
   raise exception 'Тухайн сурагч группын гишүүн биш байна.' using errcode='22023';
 end if;
 if old_row.revision is distinct from p_expected_revision then
   raise exception 'Тэмдэглэл өөрчлөгдсөн байна. Дахин ачаалаад өөрчлөлтөө оруулна уу.' using errcode='40001';
 end if;
 if p_fields is null or jsonb_typeof(p_fields)<>'object' then raise exception 'Тэмдэглэлийн өгөгдөл буруу.' using errcode='22023'; end if;
 if exists(select 1 from jsonb_object_keys(p_fields) k where k not in ('solved_problems','problem_count','difficulty','topics','notes')) then
   raise exception 'Танихгүй талбар байна.' using errcode='22023';
 end if;
 foreach fld in array array['solved_problems','difficulty','topics','notes'] loop
   field_limit:=case fld when 'solved_problems' then 12000 when 'difficulty' then 1200 when 'topics' then 2000 else 8000 end;
   if (p_fields?fld and jsonb_typeof(p_fields->fld) not in ('string','null')) or length(coalesce(p_fields->>fld,''))>field_limit then
     raise exception 'Талбарын утга эсвэл урт буруу: %',fld using errcode='22023';
   end if;
 end loop;
 if p_fields?'problem_count' and p_fields->'problem_count'<>'null'::jsonb then
   if jsonb_typeof(p_fields->'problem_count')<>'number' or (p_fields->>'problem_count') !~ '^[0-9]{1,6}$' then
     raise exception 'Бодлогын тоо 0–100000 бүхэл тоо байна.' using errcode='22023';
   end if;
   count_value:=(p_fields->>'problem_count')::integer;
   if count_value>100000 then raise exception 'Бодлогын тоо 0–100000 байна.' using errcode='22023'; end if;
 end if;
 if old_row.user_id is not null and old_row.solved_problems=coalesce(p_fields->>'solved_problems','') and
    old_row.problem_count is not distinct from count_value and old_row.difficulty=coalesce(p_fields->>'difficulty','') and
    old_row.topics=coalesce(p_fields->>'topics','') and old_row.notes=coalesce(p_fields->>'notes','') then
   return to_jsonb(old_row);
 end if;
 insert into public.study_reports as r(group_id,user_id,report_date,solved_problems,problem_count,difficulty,topics,notes,updated_by)
 values(p_group_id,p_user_id,p_date,coalesce(p_fields->>'solved_problems',''),count_value,
   coalesce(p_fields->>'difficulty',''),coalesce(p_fields->>'topics',''),coalesce(p_fields->>'notes',''),auth.uid())
 on conflict(group_id,user_id,report_date) do update set solved_problems=excluded.solved_problems,
   problem_count=excluded.problem_count,difficulty=excluded.difficulty,topics=excluded.topics,notes=excluded.notes,
   updated_by=excluded.updated_by,updated_at=now(),revision=r.revision+1
 returning * into new_row;
 insert into public.study_report_history(group_id,user_id,report_date,revision,actor_id,previous_body,new_body)
 values(p_group_id,p_user_id,p_date,new_row.revision,auth.uid(),case when old_row.user_id is null then null else to_jsonb(old_row) end,to_jsonb(new_row));
 return to_jsonb(new_row);
end;
$function$

CREATE OR REPLACE FUNCTION public.study_save_teacher_note(p_group_id uuid, p_user_id uuid, p_date date, p_note text, p_expected_revision integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_row public.study_teacher_notes%rowtype; new_row public.study_teacher_notes%rowtype;
begin
 perform 1 from public.study_groups where id=p_group_id for update;
 if not found or not study_private.can_manage(p_group_id) then
   raise exception 'Багшийн тэмдэглэл засахад группын эсвэл сайтын админ эрх шаардлагатай.' using errcode='42501';
 end if;
 if p_date is null or not isfinite(p_date) or p_note is null or length(p_note)>8000 then
   raise exception 'Огноогоо сонгож, 8000 хүртэл тэмдэгттэй тайлбар бичнэ үү.' using errcode='22023';
 end if;
 select * into old_row from public.study_teacher_notes
   where group_id=p_group_id and user_id=p_user_id and report_date=p_date for update;
 if not exists(select 1 from public.study_group_members where group_id=p_group_id and user_id=p_user_id)
   and not exists(select 1 from public.study_reports where group_id=p_group_id and user_id=p_user_id and report_date=p_date)
   and old_row.user_id is null then
   raise exception 'Тухайн өдөр энэ сурагчид тэмдэглэл үүсгэх боломжгүй.' using errcode='22023';
 end if;
 if old_row.revision is distinct from p_expected_revision then
   raise exception 'Багшийн тэмдэглэл өөрчлөгдсөн байна. Сүүлийн хувилбарыг дахин нээнэ үү.' using errcode='40001';
 end if;
 if old_row.user_id is not null and old_row.note=p_note then return to_jsonb(old_row); end if;
 insert into public.study_teacher_notes as t(group_id,user_id,report_date,note,updated_by)
 values(p_group_id,p_user_id,p_date,p_note,auth.uid())
 on conflict(group_id,user_id,report_date) do update
   set note=excluded.note,revision=t.revision+1,updated_at=now(),updated_by=excluded.updated_by
 returning * into new_row;
 insert into public.study_teacher_note_history(group_id,user_id,report_date,revision,actor_id,previous_note,new_note)
 values(p_group_id,p_user_id,p_date,new_row.revision,auth.uid(),old_row.note,p_note);
 return to_jsonb(new_row);
end;
$function$

CREATE OR REPLACE FUNCTION public.study_update_group(p_group_id uuid, p_name text, p_description text, p_visibility text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform 1 from public.study_groups where id=p_group_id for update;
 if not found or not study_private.can_manage(p_group_id) then raise exception 'Группын админ эрх шаардлагатай.' using errcode='42501'; end if;
 update public.study_groups set name=btrim(p_name),description=coalesce(p_description,''),visibility=p_visibility where id=p_group_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.track_first_progress_dates()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if TG_OP='INSERT' then
  new.first_attempted_at:=case when new.record_activity and new.status in ('trying','solved') then now() end;
  new.first_solved_at:=case when new.record_activity and new.status='solved' then now() end;
 else
  new.first_attempted_at:=old.first_attempted_at;new.first_solved_at:=old.first_solved_at;
  if new.record_activity and old.status='new' and new.status in ('trying','solved') and new.first_attempted_at is null then new.first_attempted_at:=now();end if;
  if new.record_activity and old.status<>'solved' and new.status='solved' and new.first_solved_at is null then new.first_solved_at:=now();end if;
 end if;new.record_activity:=false;return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_learning_problem(p_body jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare rate integer;tag jsonb;hints jsonb;h jsonb;field text;
begin
 if p_body is null or jsonb_typeof(p_body)<>'object' or pg_column_size(p_body)>65536 then raise exception 'Бодлогын өгөгдөл буруу эсвэл хэт том байна.'; end if;
 if nullif(btrim(p_body->>'title'),'') is null or length(p_body->>'title')>200 then raise exception 'Бодлогын нэр 1–200 тэмдэгт байна.'; end if;
 if jsonb_typeof(p_body->'source') is distinct from 'string' then raise exception 'Source нэр оруулна уу.'; end if;
 p_body:=jsonb_set(p_body,'{source}',to_jsonb(public.normalize_problem_source(p_body->>'source')));
 if lower(p_body->>'source')='codeforces' then p_body:=jsonb_set(p_body,'{source}','"Codeforces"'::jsonb); end if;
 if nullif(btrim(p_body->>'ref'),'') is null or length(p_body->>'ref')>80 then raise exception 'Эх бодлогын ID оруулна уу.'; end if;
 if not public.valid_task_url(p_body->>'url') then raise exception 'HTTPS бодлогын холбоос оруулна уу.'; end if;
 if coalesce(p_body->>'editorialUrl','')<>'' and not public.valid_task_url(p_body->>'editorialUrl') then raise exception 'Editorial HTTPS холбоос байх ёстой.'; end if;
 if p_body->>'ratingKind'='unrated' then
  if p_body->'rating' is distinct from 'null'::jsonb then raise exception 'Unrated rating null байна.'; end if;
 else
  if coalesce(p_body->>'rating','') !~ '^[0-9]{3,4}$' then raise exception 'Rating бүхэл тоо байна.'; end if;
  rate:=(p_body->>'rating')::integer;
  if rate not between 800 and 4000 then raise exception 'Rating 800–4000 хүрээнд байна.'; end if;
  if coalesce(p_body->>'ratingKind','') not in ('official','estimated') or (p_body->>'ratingKind'='official' and p_body->>'source'<>'Codeforces') then raise exception 'Rating-ийн төрөл буруу байна.'; end if;
 end if;
 if jsonb_typeof(p_body->'priority') is distinct from 'boolean' then raise exception 'Priority сонголт буруу байна.'; end if;
 if coalesce(p_body->>'level','Practice') not in ('Practice','Interactive') then raise exception 'Төрөл буруу байна.'; end if;
 if jsonb_typeof(p_body->'tags') is distinct from 'array' then raise exception 'Tags array шаардлагатай.'; end if;
 if jsonb_array_length(p_body->'tags') not between 1 and 20 then raise exception '1–20 tag оруулна уу.'; end if;
 for tag in select value from jsonb_array_elements(p_body->'tags') loop
  if jsonb_typeof(tag)<>'string' or (tag#>>'{}') !~ '^[a-zA-Z0-9 +/&()_-]{1,50}$' then raise exception 'English tag бүр 1–50 тэмдэгт байна.'; end if;
 end loop;
 for hints in select coalesce(p_body->'hints','[]'::jsonb) union all select coalesce(p_body->'hintsEn','[]'::jsonb) loop
  if jsonb_typeof(hints) is distinct from 'array' then raise exception 'Hints array шаардлагатай.'; end if;
  if jsonb_array_length(hints) not in (0,3) then raise exception 'Hint-гүй эсвэл хэл тус бүрд 3 hint байна.'; end if;
  for h in select value from jsonb_array_elements(hints) loop
   if jsonb_typeof(h)<>'string' or nullif(btrim(h#>>'{}'),'') is null or length(h#>>'{}')>3000 then raise exception 'Hint бүр 1–3000 тэмдэгт байна.'; end if;
  end loop;
 end loop;
 if jsonb_array_length(coalesce(p_body->'hints','[]'::jsonb))<>jsonb_array_length(coalesce(p_body->'hintsEn','[]'::jsonb)) then raise exception 'Хоёр хэлний hint-ийн тоо ижил байна.'; end if;
 if length(coalesce(p_body->>'lesson',''))>2000 then raise exception 'Тайлбар хэт урт байна.'; end if;
 foreach field in array array['sourceId','sourceCategory','verifiedAt','difficultyCategory','ratingBasis','ratingConfidence','ratingEstimatedAt'] loop
  if p_body ? field and (jsonb_typeof(p_body->field) is distinct from 'string' or length(p_body->>field)>500) then raise exception 'Metadata талбар буруу: %',field; end if;
 end loop;
 return p_body;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_tutorial_body(p_id text, p_body jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare lang text; v jsonb; s jsonb; b jsonb; item jsonb; cell jsonb; row_value jsonb; typ text; cols integer; ord numeric;
begin
 if p_id is null or p_id !~ '^[a-z0-9-]{1,80}$' or jsonb_typeof(p_body) is distinct from 'object' or p_body->>'id' is distinct from p_id or length(p_body::text)>1000000 then
  raise exception 'Invalid tutorial ID or payload.' using errcode='22023';
 end if;
 if coalesce(p_body->>'levelKey','') not in ('beginner','intermediate','advanced') or jsonb_typeof(p_body->'order') is distinct from 'number' then
  raise exception 'Invalid tutorial level or order.' using errcode='22023';
 end if;
 ord:=(p_body->>'order')::numeric;
 if ord<>trunc(ord) or ord not between 1 and 1000 then raise exception 'Invalid tutorial order.' using errcode='22023'; end if;
 if p_body ? 'prerequisiteIds' then
  if jsonb_typeof(p_body->'prerequisiteIds') is distinct from 'array' then raise exception 'Invalid prerequisites.' using errcode='22023'; end if;
  if jsonb_array_length(p_body->'prerequisiteIds')>30 then raise exception 'Too many prerequisites.' using errcode='22023'; end if;
  for item in select value from jsonb_array_elements(p_body->'prerequisiteIds') loop
   if jsonb_typeof(item)<>'string' or (item#>>'{}') !~ '^[a-z0-9-]{1,80}$' then raise exception 'Invalid prerequisite ID.' using errcode='22023'; end if;
  end loop;
 end if;
 perform public.tutorial_require_text(p_body->'category',80);
 perform public.tutorial_require_text(p_body->'aliases',2000);
 if jsonb_typeof(p_body->'related') is distinct from 'array' then raise exception 'Invalid related topics.' using errcode='22023'; end if;
 if jsonb_array_length(p_body->'related')>30 then raise exception 'Too many related topics.' using errcode='22023'; end if;
 for item in select value from jsonb_array_elements(p_body->'related') loop
  if jsonb_typeof(item)<>'string' or (item#>>'{}') !~ '^[a-z0-9-]{1,80}$' then raise exception 'Invalid related topic ID.' using errcode='22023'; end if;
 end loop;
 foreach lang in array array['mn','en'] loop
  v:=case when lang='mn' then p_body else p_body#>'{translations,en}' end;
  if lang='en' and (v is null or v='null'::jsonb) then continue; end if;
  if jsonb_typeof(v) is distinct from 'object' then raise exception 'Both languages are required.' using errcode='22023'; end if;
  perform public.tutorial_require_text(v->'title',200);
  perform public.tutorial_require_text(v->'summary',4000);
  perform public.tutorial_require_text(v->'prerequisites',2000);
  if jsonb_typeof(v->'sections') is distinct from 'array' then raise exception 'Invalid tutorial sections.' using errcode='22023'; end if;
  if jsonb_array_length(v->'sections') not between 1 and 80 then raise exception 'Expected 1-80 sections.' using errcode='22023'; end if;
  for s in select value from jsonb_array_elements(v->'sections') loop
   if jsonb_typeof(s) is distinct from 'object' then raise exception 'Invalid section.' using errcode='22023'; end if;
   perform public.tutorial_require_text(s->'title',200);
   if jsonb_typeof(s->'blocks') is distinct from 'array' then raise exception 'Invalid section content.' using errcode='22023'; end if;
   if jsonb_array_length(s->'blocks') not between 1 and 100 then raise exception 'Expected 1-100 content blocks.' using errcode='22023'; end if;
   for b in select value from jsonb_array_elements(s->'blocks') loop
    if jsonb_typeof(b) is distinct from 'object' then raise exception 'Invalid content block.' using errcode='22023'; end if;
    typ:=b->>'type';
    if typ in ('p','note','code') then perform public.tutorial_require_text(b->'text',40000);
    elsif typ='math' then perform public.tutorial_require_text(b->'tex',8000);
    elsif typ in ('list','ordered') then
     if jsonb_typeof(b->'items') is distinct from 'array' then raise exception 'Invalid list.' using errcode='22023'; end if;
     if jsonb_array_length(b->'items') not between 1 and 100 then raise exception 'Invalid list length.' using errcode='22023'; end if;
     for item in select value from jsonb_array_elements(b->'items') loop perform public.tutorial_require_text(item,8000); end loop;
    elsif typ='table' then
     if jsonb_typeof(b->'headers') is distinct from 'array' or jsonb_typeof(b->'rows') is distinct from 'array' then raise exception 'Invalid table.' using errcode='22023'; end if;
     cols:=jsonb_array_length(b->'headers');
     if cols not between 1 and 8 or jsonb_array_length(b->'rows') not between 1 and 100 then raise exception 'Invalid table dimensions.' using errcode='22023'; end if;
     for cell in select value from jsonb_array_elements(b->'headers') loop perform public.tutorial_require_text(cell,200); end loop;
     for row_value in select value from jsonb_array_elements(b->'rows') loop
      if jsonb_typeof(row_value) is distinct from 'array' then raise exception 'Invalid table row.' using errcode='22023'; end if;
      if jsonb_array_length(row_value)<>cols then raise exception 'Table column counts differ.' using errcode='22023'; end if;
      for cell in select value from jsonb_array_elements(row_value) loop perform public.tutorial_require_text(cell,8000); end loop;
     end loop;
    elsif typ='links' then
     if jsonb_typeof(b->'items') is distinct from 'array' then raise exception 'Invalid links.' using errcode='22023'; end if;
     if jsonb_array_length(b->'items') not between 1 and 30 then raise exception 'Invalid links length.' using errcode='22023'; end if;
     for item in select value from jsonb_array_elements(b->'items') loop
      perform public.tutorial_require_text(item->'label',300);perform public.tutorial_require_text(item->'url',1000);
      if item->>'url' !~ '^https://[^/@[:space:]]+([/?#][^[:space:]]*)?$' then raise exception 'HTTPS links are required.' using errcode='22023'; end if;
     end loop;
    else perform public.validate_tutorial_extended_block(b);
    end if;
   end loop;
  end loop;
 end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_tutorial_extended_block(b jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare typ text:=b->>'type';item jsonb;row_value jsonb;cell jsonb;n numeric;ids text[]:='{}';edge jsonb;id text;
begin
 if typ='rich' then perform public.validate_tutorial_inline(b->'content');
 elsif typ='heading' then
  perform public.tutorial_require_text(b->'text',200);
  if jsonb_typeof(b->'level') is distinct from 'number' or (b->>'level')::numeric not between 1 and 4 or (b->>'level')::numeric<>trunc((b->>'level')::numeric) then raise exception 'Expected H1-H4.' using errcode='22023';end if;
 elsif typ='divider' then return;
 elsif typ in ('callout','quote') then
  if b ? 'content' then perform public.validate_tutorial_inline(b->'content');else perform public.tutorial_require_text(b->'text',40000);end if;
  if b ? 'title' and (jsonb_typeof(b->'title')<>'string' or length(b->>'title')>200) then raise exception 'Invalid callout title.' using errcode='22023';end if;
  if typ='callout' and coalesce(b->>'tone','') not in ('note','important','warning','example','proof','observation','complexity','mistake') then raise exception 'Invalid callout tone.' using errcode='22023';end if;
 elsif typ='checklist' then
  if jsonb_typeof(b->'items') is distinct from 'array' then raise exception 'Invalid checklist.' using errcode='22023';end if;
  if jsonb_array_length(b->'items') not between 1 and 100 then raise exception 'Invalid checklist size.' using errcode='22023';end if;
  for item in select value from jsonb_array_elements(b->'items') loop
   perform public.tutorial_require_text(item->'text',8000);if jsonb_typeof(item->'checked') is distinct from 'boolean' then raise exception 'Invalid checklist state.' using errcode='22023';end if;
  end loop;
 elsif typ='image' then
  perform public.tutorial_require_text(b->'alt',500);
  if coalesce(b->>'path','') !~ '^[a-z0-9-]{1,80}/[0-9a-f-]{36}/[0-9a-f-]{36}\.webp$' or coalesce(b->>'align','') not in ('left','center','right') then raise exception 'Invalid image reference.' using errcode='22023';end if;
  if jsonb_typeof(b->'width') is distinct from 'number' or (b->>'width')::numeric not between 20 and 100 or (b->>'width')::numeric<>trunc((b->>'width')::numeric) then raise exception 'Image width must be 20-100 percent.' using errcode='22023';end if;
 elsif typ='problem' then
  if coalesce(b->>'problemKey','') !~ '^[a-zA-Z0-9 ._-]+\|[a-zA-Z0-9_/-]+$' then raise exception 'Invalid embedded problem.' using errcode='22023';end if;
 elsif typ='tutorial' then
  if coalesce(b->>'tutorialId','') !~ '^[a-z0-9-]{1,80}$' then raise exception 'Invalid embedded tutorial.' using errcode='22023';end if;
 elsif typ='diagram' then
  if coalesce(b->>'kind','') not in ('array','dp','graph','tree') then raise exception 'Invalid diagram type.' using errcode='22023';end if;
  if b->>'kind' in ('array','dp') then
   if jsonb_typeof(b->'rows') is distinct from 'array' then raise exception 'Invalid diagram rows.' using errcode='22023';end if;
   if jsonb_array_length(b->'rows') not between 1 and 20 then raise exception 'Invalid diagram row count.' using errcode='22023';end if;
   for row_value in select value from jsonb_array_elements(b->'rows') loop
    if jsonb_typeof(row_value) is distinct from 'array' then raise exception 'Invalid diagram row.' using errcode='22023';end if;
    if jsonb_array_length(row_value) not between 1 and 30 then raise exception 'Invalid diagram cells.' using errcode='22023';end if;
    for cell in select value from jsonb_array_elements(row_value) loop perform public.tutorial_require_text(cell,500);end loop;
   end loop;
  else
   if jsonb_typeof(b->'nodes') is distinct from 'array' or jsonb_typeof(b->'edges') is distinct from 'array' then raise exception 'Invalid graph diagram.' using errcode='22023';end if;
   if jsonb_array_length(b->'nodes') not between 1 and 30 or jsonb_array_length(b->'edges')>100 then raise exception 'Graph diagram too large.' using errcode='22023';end if;
   for item in select value from jsonb_array_elements(b->'nodes') loop
    perform public.tutorial_require_text(item->'id',50);perform public.tutorial_require_text(item->'label',500);id:=item->>'id';if id=any(ids) then raise exception 'Duplicate diagram node.' using errcode='22023';end if;ids:=array_append(ids,id);
    foreach id in array array['x','y'] loop
     if item ? id then
      if jsonb_typeof(item->id) is distinct from 'number' then raise exception 'Invalid diagram coordinate.' using errcode='22023';end if;n:=(item->>id)::numeric;if n not between 5 and 95 then raise exception 'Diagram coordinates must be 5-95.' using errcode='22023';end if;
     end if;
    end loop;
   end loop;
   for edge in select value from jsonb_array_elements(b->'edges') loop
    if jsonb_typeof(edge) is distinct from 'array' then raise exception 'Invalid diagram edge.' using errcode='22023';end if;
    if jsonb_array_length(edge)<>2 or not ((edge->>0)=any(ids)) or not ((edge->>1)=any(ids)) then raise exception 'Unknown diagram node.' using errcode='22023';end if;
   end loop;
  end if;
  if b ? 'highlights' then
   if jsonb_typeof(b->'highlights') is distinct from 'array' or jsonb_array_length(b->'highlights')>100 then raise exception 'Invalid highlights.' using errcode='22023';end if;
   for item in select value from jsonb_array_elements(b->'highlights') loop perform public.tutorial_require_text(item,50);end loop;
  end if;
 else raise exception 'Unsupported tutorial block type.' using errcode='22023';
 end if;
 if b ? 'caption' and (jsonb_typeof(b->'caption')<>'string' or length(b->>'caption')>2000) then raise exception 'Invalid caption.' using errcode='22023';end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_tutorial_inline(p_content jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare item jsonb;mark jsonb;total integer:=0;nonempty boolean:=false;
begin
 if jsonb_typeof(p_content) is distinct from 'array' then raise exception 'Invalid rich text.' using errcode='22023';end if;
 if jsonb_array_length(p_content) not between 1 and 1000 then raise exception 'Invalid rich text size.' using errcode='22023';end if;
 for item in select value from jsonb_array_elements(p_content) loop
  if jsonb_typeof(item->'text') is distinct from 'string' or length(item->>'text')>40000 then raise exception 'Invalid rich text item.' using errcode='22023';end if;
  total:=total+length(item->>'text');nonempty:=nonempty or length(btrim(item->>'text'))>0;
  if item ? 'marks' then
   if jsonb_typeof(item->'marks') is distinct from 'array' or jsonb_array_length(item->'marks')>20 then raise exception 'Invalid rich marks.' using errcode='22023';end if;
   for mark in select value from jsonb_array_elements(item->'marks') loop
    if jsonb_typeof(mark)<>'string' or (mark#>>'{}') not in ('bold','italic','underline','strike','code') then raise exception 'Unsupported rich mark.' using errcode='22023';end if;
   end loop;
  end if;
  if item ? 'href' and not public.safe_tutorial_link(item->>'href') then raise exception 'Unsafe inline link.' using errcode='22023';end if;
 end loop;
 if not nonempty or total>40000 then raise exception 'Rich text is empty or too large.' using errcode='22023';end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_tutorial_publication(p_id text, p_body jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item jsonb;rel jsonb;row_value jsonb;k text;cycle_found boolean;
begin
 perform pg_catalog.pg_advisory_xact_lock(72483161);
 if p_body ? '_draftRelationsText' then raise exception 'Private draft metadata cannot be published.' using errcode='22023';end if;
 perform public.validate_tutorial_body(p_id,p_body);
 for item in select value from jsonb_array_elements(coalesce(p_body->'prerequisiteIds','[]'::jsonb)) loop
  if item#>>'{}'=p_id or not exists(select 1 from public.tutorial_catalog where id=item#>>'{}' and published) then raise exception 'Missing published prerequisite: %',item#>>'{}' using errcode='22023';end if;
 end loop;
 with recursive paths(id,path,cycle) as (
  select value#>>'{}',array[p_id,value#>>'{}'],(value#>>'{}')=p_id from jsonb_array_elements(coalesce(p_body->'prerequisiteIds','[]'::jsonb))
  union all select x.value#>>'{}',p.path||(x.value#>>'{}'),(x.value#>>'{}')=any(p.path)
  from paths p join public.tutorial_catalog t on t.id=p.id cross join lateral jsonb_array_elements(coalesce(t.body->'prerequisiteIds','[]'::jsonb)) x(value) where not p.cycle
 ) select exists(select 1 from paths where cycle) into cycle_found;
 if cycle_found then raise exception 'Prerequisite cycle.' using errcode='22023';end if;
 rel:=p_body->'learningRelations';
 if rel is not null then
  if jsonb_typeof(rel) is distinct from 'object' or jsonb_typeof(rel->'practice') is distinct from 'array' or jsonb_typeof(rel->'variants') is distinct from 'array' then raise exception 'Invalid tutorial relationships.' using errcode='22023';end if;
  if jsonb_array_length(rel->'practice') not between 1 and 30 or jsonb_array_length(rel->'variants')>20 then raise exception 'Expected 1-30 practice tasks, at most 20 variants.' using errcode='22023';end if;
  if not exists(select 1 from jsonb_array_elements(rel->'practice') x where x->'priority'='true'::jsonb) then raise exception 'Select at least one priority task.' using errcode='22023';end if;
  if (select count(*)<>count(distinct value->>'key') from jsonb_array_elements(rel->'practice')) then raise exception 'Duplicate practice task.' using errcode='22023';end if;
  for row_value in select value from jsonb_array_elements(rel->'practice') loop
   k:=row_value->>'key';
   if not exists(select 1 from public.problem_catalog where not archived and coalesce('cses|'||(regexp_match(body->>'url','^https://cses[.]fi/problemset/task/([0-9]+)/?([?#].*)?$'))[1],lower(btrim(body->>'source'))||'|'||lower(btrim(body->>'ref')))=k) then raise exception 'Unknown practice task: %',k using errcode='22023';end if;
   if coalesce(row_value->>'stage','') not in ('Warm-up','Standard','Observation','Application','Challenge','Olympiad extension') or jsonb_typeof(row_value->'priority') is distinct from 'boolean' then raise exception 'Invalid practice stage/priority.' using errcode='22023';end if;
   if row_value->'priority'='true'::jsonb then perform public.tutorial_require_text(row_value->'reason',1000);end if;
   if row_value ? 'objective' and (jsonb_typeof(row_value->'objective')<>'string' or length(row_value->>'objective')>1500) then raise exception 'Invalid learning objective.' using errcode='22023';end if;
  end loop;
  for row_value in select value from jsonb_array_elements(rel->'variants') loop
   if coalesce(row_value->>'tutorialId','') !~ '^[a-z0-9-]{1,80}$' or row_value->>'tutorialId'=p_id or not exists(select 1 from public.tutorial_catalog where id=row_value->>'tutorialId' and published) then raise exception 'Invalid variant ID.' using errcode='22023';end if;
   perform public.tutorial_require_text(row_value->'description',1000);
   if row_value ? 'descriptionEn' and (jsonb_typeof(row_value->'descriptionEn')<>'string' or length(row_value->>'descriptionEn')>1000) then raise exception 'Invalid variant description.' using errcode='22023';end if;
  end loop;
  if rel->>'next' is not null and ((rel->>'next') !~ '^[a-z0-9-]{1,80}$' or rel->>'next'=p_id or not exists(select 1 from public.tutorial_catalog where id=rel->>'next' and published)) then raise exception 'Invalid next tutorial.' using errcode='22023';end if;
 end if;
 return;
end;
$function$
